"""Lux 0.79.0: a morning and a high noon (the factory's roadmap 217).

The walker's five times of day (2026-10-07) had three presets; the look review of 2026-10-19 asked for the morning
and the noon: "Build both". New files only, so nothing existing is edited; the patch refuses to write over any of
them, refuses a VERSION or a CHANGELOG that is not 0.78.0's, and writes nothing on a refusal.

What it writes:
  * addons/lux/presets/delco_morning.tres, addons/lux/presets/delco_high_noon.tres -- the two presets.
  * tools/day_presets_selftest.gd (+ its .uid) -- fails on 0.78.0.
  * VERSION Lux 0.78.0 -> Lux 0.79.0, CHANGELOG (the entry under its `# Changelog` header).

Copied from a proven clone (scratchpad lux_tod: every Lux self-test exit 0 there); the factory's
`patches/lux_day_presets/` keeps the dry runs, the prove run and the self-tests.

    python patches/patch_lux_day_presets.py
"""
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
LUX = ROOT / "lux"
NEW_FILES = {'addons/lux/presets/delco_morning.tres': '[gd_resource type="Resource" script_class="LuxPreset" load_steps=3 format=3 uid="uid://lux_delco_morning"]\n\n[ext_resource type="Script" path="res://addons/lux/resources/lux_preset.gd" id="1_preset"]\n[ext_resource type="Script" path="res://addons/lux/resources/lux_palette.gd" id="2_palette"]\n\n[sub_resource type="Resource" id="pal"]\nscript = ExtResource("2_palette")\npalette_name = &"Delco Morning"\nhighlight = Color(0.56, 0.53, 0.44, 1)\nmidtone = Color(0.5, 0.49, 0.46, 1)\nshadow = Color(0.4, 0.44, 0.58, 1)\nfog = Color(0.76, 0.78, 0.76, 1)\naccent = Color(1, 0.55, 0.2, 1)\n\n[resource]\nscript = ExtResource("1_preset")\nstreet_lamps_lit = false\npreset_name = &"Delco Morning"\ndescription = "Clear early morning, the sun low in the east-southeast: golden light, long cool shade, a little haze."\nsky_top_color = Color(0.4, 0.58, 0.82, 1)\nsky_horizon_color = Color(0.86, 0.82, 0.74, 1)\nground_color = Color(0.3, 0.27, 0.22, 1)\nsky_energy = 1.1\nhorizon_glow_color = Color(0.92, 0.88, 0.8, 1)\nhorizon_glow_energy = 0.4\nhorizon_glow_top_deg = 10.0\nsun_enabled = true\nsun_elevation_deg = 28.0\nsun_azimuth_deg = 100.0\nsun_color = Color(1, 0.9, 0.76, 1)\nsun_energy = 1.3\nsun_shadows = true\nsun_shadow_mode = 0\nsun_shadow_max_distance = 60.0\nambient_color = Color(0.56, 0.6, 0.68, 1)\nambient_energy = 1.0\nfluorescent_energy_scale = 1.0\nroom_probes_replace_ambient = true\ntonemap_mode = 2\nexposure = 1.0\ntonemap_white = 6.0\nbrightness = 1.0\ncontrast = 1.0\nsaturation = 1.02\nwarmth = 0.18\nfog_enabled = true\nfog_color = Color(0.8, 0.82, 0.8, 1)\nfog_density = 0.0045\nfog_sky_affect = 0.2\nglow_enabled = true\nglow_intensity = 0.35\nglow_bloom = 0.05\nglow_hdr_threshold = 1.1\ndither_enabled = true\ndither_strength = 0.22\ncolor_levels = 28\ndither_cell_size = 1\ndither_distance_fade = true\ndither_fade_start = 30.0\ndither_fade_end = 80.0\nvignette_strength = 0.12\ngrain_strength = 0.025\npalette_influence = 0.25\npalette = SubResource("pal")\ndefault_wetness = 0.0\nalarm_color = Color(1, 0.15, 0.22, 1)\n', 'addons/lux/presets/delco_high_noon.tres': '[gd_resource type="Resource" script_class="LuxPreset" load_steps=3 format=3 uid="uid://lux_delco_high_noon"]\n\n[ext_resource type="Script" path="res://addons/lux/resources/lux_preset.gd" id="1_preset"]\n[ext_resource type="Script" path="res://addons/lux/resources/lux_palette.gd" id="2_palette"]\n\n[sub_resource type="Resource" id="pal"]\nscript = ExtResource("2_palette")\npalette_name = &"Delco Noon"\nhighlight = Color(0.58, 0.56, 0.5, 1)\nmidtone = Color(0.5, 0.49, 0.46, 1)\nshadow = Color(0.42, 0.44, 0.55, 1)\nfog = Color(0.76, 0.78, 0.8, 1)\naccent = Color(1, 0.55, 0.2, 1)\n\n[resource]\nscript = ExtResource("1_preset")\nstreet_lamps_lit = false\npreset_name = &"Delco High Noon"\ndescription = "Summer high noon, the sun high in the south: hard white light, short shadows, a deep clear sky."\nsky_top_color = Color(0.28, 0.48, 0.8, 1)\nsky_horizon_color = Color(0.78, 0.82, 0.86, 1)\nground_color = Color(0.3, 0.27, 0.22, 1)\nsky_energy = 1.2\nhorizon_glow_color = Color(0.88, 0.9, 0.92, 1)\nhorizon_glow_energy = 0.3\nhorizon_glow_top_deg = 10.0\nsun_enabled = true\nsun_elevation_deg = 70.0\nsun_azimuth_deg = 180.0\nsun_color = Color(1, 0.98, 0.93, 1)\nsun_energy = 1.8\nsun_shadows = true\nsun_shadow_mode = 0\nsun_shadow_max_distance = 60.0\nambient_color = Color(0.62, 0.64, 0.66, 1)\nambient_energy = 1.15\nfluorescent_energy_scale = 1.0\nroom_probes_replace_ambient = true\ntonemap_mode = 2\nexposure = 1.0\ntonemap_white = 6.0\nbrightness = 1.0\ncontrast = 1.04\nsaturation = 1.05\nwarmth = 0.12\nfog_enabled = true\nfog_color = Color(0.8, 0.82, 0.84, 1)\nfog_density = 0.0025\nfog_sky_affect = 0.2\nglow_enabled = true\nglow_intensity = 0.35\nglow_bloom = 0.05\nglow_hdr_threshold = 1.1\ndither_enabled = true\ndither_strength = 0.22\ncolor_levels = 28\ndither_cell_size = 1\ndither_distance_fade = true\ndither_fade_start = 30.0\ndither_fade_end = 80.0\nvignette_strength = 0.12\ngrain_strength = 0.025\npalette_influence = 0.25\npalette = SubResource("pal")\ndefault_wetness = 0.0\nalarm_color = Color(1, 0.15, 0.22, 1)\n', 'tools/day_presets_selftest.gd': 'extends SceneTree\n## The morning and the high noon (0.79.0, the factory\'s roadmap 217).\n##\n##     godot --headless --path lux --import\n##     godot --headless --path lux -s res://tools/day_presets_selftest.gd\n##\n## Exit 0 = every case behaved. Exit 1 = a case failed (the message says\n## which). Exit 2 = could not run at all, which is never reported as a pass.\n##\n## The walker, 2026-10-07: every level is set at one of five times -- morning,\n## high noon, afternoon, evening, midnight. Three had a preset; a brief asking\n## for morning or noon got Gas Station Fluorescent. The walker\'s look review,\n## 2026-10-19: "Build both". Headless has no renderer, so nothing here says a\n## morning READS as a morning -- that is the frames\' and the walker\'s. What\n## this holds is what a day preset must be to stand in the day:\n##\n##   * both load from the preset folder under their display names, which is\n##     how LuxRoot registers them (`_preset_library`) and how Level Factory\n##     asks for them;\n##   * each is a day: the sun on and casting, the street lamps dark;\n##   * the sun keeps the day\'s order -- morning low in the east-southeast,\n##     the afternoon\'s 46 degrees in the south-southwest, noon high in the\n##     south -- and the morning stays well above Blue Hour\'s 4 degrees, the\n##     angle the walker called "very hard for lighting";\n##   * the sky is a day\'s (energy at least the afternoon\'s), so the\n##     fluorescents stay at their daylight scale, 1.0\n##     (`fluorescent_scale_selftest.gd` derives it for every preset).\n##\n## FAILS ON 0.78.0: neither preset exists.\n\nconst PRESETS := "res://addons/lux/presets/"\nconst AFTERNOON := "delco_summer_afternoon.tres"\nconst MORNING := "delco_morning.tres"\nconst NOON := "delco_high_noon.tres"\n\nvar _fails: int = 0\n\n\nfunc _initialize() -> void:\n\t_main()\n\n\nfunc _check(label: String, ok: bool, got: Variant) -> void:\n\tif not ok:\n\t\t_fails += 1\n\tprint("  %s %s: %s" % ["ok  " if ok else "FAIL", label, str(got)])\n\n\nfunc _load(file: String) -> LuxPreset:\n\tif not ResourceLoader.exists(PRESETS + file):\n\t\treturn null\n\treturn load(PRESETS + file) as LuxPreset\n\n\nfunc _registered() -> Dictionary:\n\t# the names LuxRoot\'s library would register, read the way it reads them\n\tvar out := {}\n\tvar d := DirAccess.open(PRESETS)\n\tif d == null:\n\t\treturn out\n\tfor fn in d.get_files():\n\t\tif fn.ends_with(".tres"):\n\t\t\tvar p := load(PRESETS + fn) as LuxPreset\n\t\t\tif p != null:\n\t\t\t\tout[String(p.preset_name)] = fn\n\treturn out\n\n\nfunc _main() -> void:\n\tvar afternoon := _load(AFTERNOON)\n\tif afternoon == null:\n\t\tprint("CANNOT RUN: %s does not load" % AFTERNOON)\n\t\tquit(2)\n\t\treturn\n\tvar morning := _load(MORNING)\n\tvar noon := _load(NOON)\n\t_check("Delco Morning loads", morning != null, MORNING)\n\t_check("Delco High Noon loads", noon != null, NOON)\n\tif morning == null or noon == null:\n\t\tprint("%d FAILED" % _fails)\n\t\tquit(1)\n\t\treturn\n\tvar names := _registered()\n\t_check("registered as Delco Morning", names.get("Delco Morning", "") == MORNING, names.get("Delco Morning", ""))\n\t_check("registered as Delco High Noon", names.get("Delco High Noon", "") == NOON, names.get("Delco High Noon", ""))\n\tfor p in [morning, noon]:\n\t\tvar n := String(p.preset_name)\n\t\t_check(n + ": the sun on", p.sun_enabled, p.sun_enabled)\n\t\t_check(n + ": the sun casts", p.sun_shadows, p.sun_shadows)\n\t\t_check(n + ": the street lamps dark", not p.street_lamps_lit, p.street_lamps_lit)\n\t\t_check("%s: a day\'s sky (>= the afternoon\'s %.2f)" % [n, afternoon.sky_energy],\n\t\t\tp.sky_energy >= afternoon.sky_energy - 1e-6, p.sky_energy)\n\t\t_check(n + ": fluorescents at the daylight scale", is_equal_approx(p.fluorescent_energy_scale, 1.0),\n\t\t\tp.fluorescent_energy_scale)\n\t_check("the sun climbs: morning < afternoon < noon",\n\t\tmorning.sun_elevation_deg < afternoon.sun_elevation_deg and afternoon.sun_elevation_deg < noon.sun_elevation_deg,\n\t\t[morning.sun_elevation_deg, afternoon.sun_elevation_deg, noon.sun_elevation_deg])\n\t_check("the morning well above Blue Hour\'s 4 degrees (>= 20)", morning.sun_elevation_deg >= 20.0,\n\t\tmorning.sun_elevation_deg)\n\t_check("noon high (>= 60)", noon.sun_elevation_deg >= 60.0, noon.sun_elevation_deg)\n\t_check("the morning sun in the east-southeast (80-140)",\n\t\tmorning.sun_azimuth_deg >= 80.0 and morning.sun_azimuth_deg <= 140.0, morning.sun_azimuth_deg)\n\t_check("the noon sun in the south (170-190)",\n\t\tnoon.sun_azimuth_deg >= 170.0 and noon.sun_azimuth_deg <= 190.0, noon.sun_azimuth_deg)\n\t_check("the afternoon sun west of south (> 190)", afternoon.sun_azimuth_deg > 190.0, afternoon.sun_azimuth_deg)\n\t_check("noon brighter than morning", noon.sun_energy > morning.sun_energy, [morning.sun_energy, noon.sun_energy])\n\tif _fails:\n\t\tprint("%d FAILED" % _fails)\n\t\tquit(1)\n\t\treturn\n\tprint("all day presets behaved")\n\tquit(0)\n', 'tools/day_presets_selftest.gd.uid': 'uid://d0qr1hxhtblh0\n'}
CHANGELOG = '## [0.79.0] - a morning and a high noon\n\n**The factory\'s roadmap 217.** The walker, 2026-10-07: a level is set at one of five times -- morning, high noon,\nafternoon, evening, midnight. Three had a preset (Delco Summer Afternoon, Blue Hour, Delco Night), so Level Factory\nsent a brief asking for morning or noon to Gas Station Fluorescent, an interior look. The walker\'s look review,\n2026-10-19, on the morning and noon presets: "Build both".\n\n### Added\n- `presets/delco_morning.tres`, **Delco Morning**: the afternoon baseline with the fields the hour moves. The sun is\n  28 degrees up from the east-southeast (azimuth 100), golden-white (1, 0.9, 0.76) at 1.3. The sky is paler at the\n  top over a warm, hazy horizon, with a little more fog (0.0045, against the afternoon\'s 0.0035). The ambient is\n  cooler (0.56, 0.6, 0.68) at 1.0, and the palette\'s shadow is bluer.\n- `presets/delco_high_noon.tres`, **Delco High Noon**: the sun is 70 degrees up from due south (Delaware County\'s\n  midsummer noon is about 73), near white (1, 0.98, 0.93) at 1.8. The sky is a deeper blue at the top, and clearer\n  (fog 0.0025, sky energy 1.2). The ambient is 1.15, with less warmth (0.12) and a little more contrast (1.04).\n- Both are days: the sun is on and casting, the street lamps dark, and the fluorescents at the daylight scale 1.0\n  that `fluorescent_scale_selftest.gd` derives from each sky. Neither hands the sky to a provider; Lux draws it.\n- `tools/day_presets_selftest.gd`. Both presets load and register under their display names. Each is a day. The sun\n  climbs morning < afternoon < noon (28 < 46 < 70), the morning well above Blue Hour\'s 4 degrees (the walker: that\n  angle is "very hard for lighting"), and each sun stands in its quarter of the sky. It fails on 0.78.0, where\n  neither preset exists.\n\n### Not measured here\nHeadless draws nothing, so whether a morning reads as a morning is the frames\' to show and the walker\'s to say. The\nfactory\'s cold runs that first set a level at each are where that is recorded.\n\n'
OLD_VERSION, NEW_VERSION = "Lux 0.78.0", "Lux 0.79.0"
HEADER = "# Changelog\n\n"


def main(argv):
    for name in NEW_FILES:
        if (LUX / name).exists():
            raise SystemExit("REFUSED: lux/%s exists already; nothing written" % name)
    v = LUX / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LUX / "CHANGELOG.md"
    craw = cl.read_bytes().decode("utf-8")
    if "\r\n" in craw or not craw.startswith(HEADER + "## [" + OLD_VERSION.split()[-1] + "]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on its header and %s; nothing written" % OLD_VERSION)
    for name, text in NEW_FILES.items():
        (LUX / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes((HEADER + CHANGELOG + craw[len(HEADER):]).encode("utf-8"))
    print("%s applied: %d files written, VERSION, CHANGELOG. Now, in lux/: the import and the self-tests"
          % (NEW_VERSION, len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
